const db = require('../models/db');

function dateOnly(value) {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  return String(value).split('T')[0].slice(0, 10);
}

// The INVOICE-MODE recurring accept mints its combined first-visit invoice
// with different notes (estimate-public.js buildEstimateInvoiceModeDraft:
// "Auto-generated from accepted estimate #<id> (invoice-mode recurring). …")
// and never the "customer selected pay per application" sentence, so the
// recognizer above does not match it. The BACKFILL alone (historical pairs
// and the runtime reconciliation) accepts this second, equally provenance-
// bearing format (Codex pre-push P1 on a0a05a61e6, PR #5021); membership
// still needs the same accept-time window and original-date evidence. The
// lookup and the void guard keep the narrow recognizer: a stamped visit is
// found by its stamp regardless of text.
// The scheduled_services ids an invoice's own line items name via the shared
// base-application identity (client_id `scheduled_<id>_primary`, written by
// itemizeFirstApplication at accept and by every service mint). Durable
// membership evidence that survives a lost reschedule audit row.
function itemizedMemberIdsFromInvoiceLines(lineItems) {
  let items = lineItems;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (!Array.isArray(items)) return new Set();
  const out = new Set();
  for (const li of items) {
    const m = /^scheduled_(.+)_primary$/.exec(String(li?.client_id || ''));
    if (m) out.add(m[1]);
  }
  return out;
}

function isInvoiceModeRecurringAcceptInvoice(invoice = {}) {
  const notes = String(invoice.notes || '').toLowerCase();
  return notes.includes('auto-generated from accepted estimate') && notes.includes('(invoice-mode recurring)');
}
function isCombinedFirstApplicationInvoiceForBackfill(invoice = {}) {
  return isAutoGeneratedPayPerApplicationInvoice(invoice) || isInvoiceModeRecurringAcceptInvoice(invoice);
}

function isAutoGeneratedPayPerApplicationInvoice(invoice = {}) {
  const title = String(invoice.title || '').toLowerCase();
  const notes = String(invoice.notes || '').toLowerCase();
  return notes.includes('auto-generated from accepted estimate')
    && notes.includes('customer selected pay per application')
    && (title.includes('first application') || notes.includes('first application'));
}

// Where a row stood AT A GIVEN INSTANT (Codex round 14 P1 on PR #5021 —
// replaces round 13's "earliest original_date ever"): the pairing question is
// "were anchor and sibling on the same day when the combined invoice was
// minted", not "where did each row start". A reserved anchor rescheduled
// BEFORE acceptance (Oct 1 → Oct 5, then the accept creates the sibling on
// Oct 5) has earliest original_date Oct 1 and was wrongly rejected. From
// reschedule_log (columns per the frozen 20260401000022_reschedule_system.js:
// scheduled_service_id, original_date, new_date, created_at):
//   1. the LATEST move logged at or before `instant` → its new_date (where
//      that move left the row, and nothing moved it again before `instant`);
//   2. else, the EARLIEST move logged after `instant` → its original_date
//      (where the row stood just before its first later move);
//   3. else (never moved) → its current scheduled_date.
// A NULL date on the chosen log row falls through to the next rule, never to
// a guess. hasRescheduleLog false (table missing — should not happen in this
// app) → the current scheduled_date alone; this backfill fails toward NOT
// stamping, never toward an unguarded query error.
async function dateAtInstant(conn, hasRescheduleLog, rowId, currentDate, instant) {
  if (hasRescheduleLog && instant) {
    const before = await conn('reschedule_log')
      .where({ scheduled_service_id: rowId })
      .where('created_at', '<=', instant)
      .whereNotNull('new_date')
      .orderBy('created_at', 'desc')
      .first('new_date');
    if (before?.new_date) return dateOnly(before.new_date);
    const after = await conn('reschedule_log')
      .where({ scheduled_service_id: rowId })
      .where('created_at', '>', instant)
      .whereNotNull('original_date')
      .orderBy('created_at', 'asc')
      .first('original_date');
    if (after?.original_date) return dateOnly(after.original_date);
  }
  return dateOnly(currentDate);
}

// One-time (bounded, idempotent, RERUNNABLE) backfill of scheduled_services.
// first_application_invoice_id for historical combined first-application
// invoices — owner ruling 2026-09-27. Shared by the schema migration
// (20260927220000, frozen — pushed and never edited) AND the later
// re-run migration (20260928000000) that widens this same function's own
// eligibility without touching the frozen one; also directly
// testable/callable by hand against a live database. Candidate INVOICES
// are still found the OLD way — isAutoGeneratedPayPerApplicationInvoice's
// title/notes text match on a non-void invoice, joined to its own anchor
// visit — there being no stamp yet at all is exactly the problem this
// backfill exists to solve, so text is the only evidence available for
// discovering the historical invoice itself. Invoices are processed in
// created_at order (oldest first) so the result is deterministic.
//
// SIBLING eligibility (P1-A, Codex round 13 — tightens round-11 P2's
// accept-time created_at window, which by itself proved NOT membership
// evidence on its own: (1) two acceptances under the SAME estimate close
// enough together (e.g. 60 seconds apart) put every row from BOTH accepts
// inside EACH OTHER's 120-second window, so the window alone could
// cross-stamp or overwrite the wrong accept's members; (2) the converter
// also creates unpriced recurring parents at accept that are NOT same-trip
// at all — a seasonal unit rolled to a later month, or a companion outside
// the reservation — which land inside the window too even though they
// were never on the anchor's day to begin with). A sibling now needs BOTH:
//   (a) scheduled_services.created_at within 120 seconds of the INVOICE's
//       own created_at (not the anchor's — a reserved-slot anchor can be
//       minted days before the invoice, while the invoice and every
//       promoted sibling are inserted together AT acceptance), AND
//   (b) its date AT THE INVOICE'S created_at (dateAtInstant above) equals
//       the anchor's date at that same instant — the genuine same-trip
//       signal a plain window match cannot provide: two rows born in the
//       same accept transaction but never actually scheduled together (a
//       seasonal roll, a companion outside the reservation) were on
//       DIFFERENT days at accept even though their created_at instants
//       coincide, while a genuine same-trip pair that has since diverged
//       was on the same day when the invoice was minted, regardless of where
//       either row moved before or after that (Codex round 14 P1: a reserved
//       anchor moved BEFORE accept is judged where it stood at accept, not
//       where it was first booked).
// Also required, independent of the pairing above: never overwrite a
// sibling's stamp (only sibling rows with first_application_invoice_id IS
// NULL are considered); an ANCHOR is accepted unstamped OR already stamped
// with THIS invoice (Codex round 14 P1: a three-program group the first
// migration partially stamped — anchor + aligned sibling — must still be
// extendable by the rerun to its moved third member), never one stamped to a
// different invoice; and never treat a row as a sibling
// (or as an anchor) when it is ITSELF the scheduled_service_id anchor of
// some OTHER live (non-void) invoice — that row already has its own
// combined-invoice identity and must not be folded into a different
// group's membership.
//
// AMBIGUITY: if a single candidate sibling row satisfies (a) and (b) for
// MORE than one candidate invoice in this run (the two-close-acceptances
// case above, when both accepts' rows also stood on the exact same date
// at invoice creation), this backfill stamps NOTHING for that row — it is
// counted as `ambiguous` and logged (id only) for the office to resolve by
// hand, rather than guessing which invoice actually owns it. A raw
// candidate that satisfies the created_at window (a) but fails the
// date-at-invoice match (b) for every candidate invoice it was compared
// against is similarly left unstamped and logged, so the office can review
// it too — it fell inside the timing window but this backfill found no
// same-trip evidence for it.
//
// A single-program invoice (no eligible, non-ambiguous sibling) is never
// stamped as a pair. Idempotent: the stamp write itself is guarded by
// first_application_invoice_id IS NULL, so a rerun only ever adds NEW stamps
// for rows not yet stamped — it never rewrites a decision it (or a real
// accept-time stamp) already committed — and `stamped` counts exactly the
// rows this run newly stamped.
// `sinceDays` (Codex r15 P1 on PR #5021 — pre-deploy write gap): the two
// migrations run in Railway's pre-deploy phase while the previous app
// version still serves traffic, so an accept on an old pod after the rerun
// finished is never stamped by anyone. The sibling-split sweep therefore
// re-runs this exact, never-overwriting backfill on every tick, bounded to
// invoices created in the last `sinceDays` days, as the runtime
// reconciliation path. null = unbounded (the migrations' one-time runs).
async function backfillFirstApplicationInvoiceStamps(conn = db, { sinceDays = null } = {}) {
  const hasColumn = await conn.schema.hasColumn('scheduled_services', 'first_application_invoice_id');
  if (!hasColumn) return { scanned: 0, stamped: 0, ambiguous: 0 };
  const logger = require('./logger');
  const hasRescheduleLog = await conn.schema.hasTable('reschedule_log');

  // A row is never a candidate (anchor OR sibling) once it is already
  // stamped, or while it is itself the scheduled_service_id anchor of some
  // OTHER live invoice — shared by both the anchor query below and the
  // per-invoice sibling query further down. excludeInvoiceAlias lets the
  // anchor query exclude the CURRENT candidate invoice itself from "other"
  // (every anchor row trivially IS the scheduled_service_id of its own
  // invoice `i` — without this exclusion every anchor would always fail
  // its own check); the sibling query passes none, since a sibling row is
  // never the current invoice's own anchor by construction (`s.id <>
  // anchor_id` is already enforced by its own where clause).
  // excludeInvoiceAlias also marks the ANCHOR query: an anchor already stamped
  // with that same invoice is still a candidate (a partially stamped group is
  // extended, never re-stamped); a sibling must be unstamped.
  // Extending a PARTIALLY stamped group (anchor already stamped to this same
  // invoice, a sibling still unstamped) is HISTORICAL repair only: the first
  // frozen migration stamped anchor + still-aligned sibling and missed the
  // already-moved one. It is allowed solely on the unbounded run the
  // migrations make (sinceDays null). The bounded runtime reconciliation
  // the sweep runs every tick considers UNSTAMPED anchors only: a recent
  // invoice's accept-time stamp is authoritative membership, and inferring
  // an extra same-day unpriced row into it would undo the stamper's explicit
  // memberIds exclusion of a bystander program (Codex pre-push P1 on
  // 15bb180830, PR #5021).
  const extendPartialGroups = sinceDays == null;
  const notAlreadyClaimed = (query, alias, excludeInvoiceAlias = null) => query
    .where(function unstampedOrStampedToThisInvoice() {
      this.whereNull(`${alias}.first_application_invoice_id`);
      if (excludeInvoiceAlias && extendPartialGroups) this.orWhereRaw(`${alias}.first_application_invoice_id = ${excludeInvoiceAlias}.id`);
    });
  // Ownership by ANOTHER invoice is decided in JS, not SQL (Codex r17 P1):
  // several invoices can share one visit (an add-on, a repair), and only a
  // LIVE invoice that actually BILLS THE BASE APPLICATION
  // (invoiceBillsBaseApplication — the shared client_id
  // `scheduled_<id>_primary` / "First service application" identity) proves
  // the visit's application is invoiced elsewhere. Any other live invoice on
  // the row is irrelevant to membership. "Live" = the full resolved
  // vocabulary excluded (Codex r15 P2).
  const liveBaseApplicationInvoiceVisitIds = (visitIds, opts = {}) => liveBaseApplicationInvoiceVisitIdsOn(conn, visitIds, opts);

  const candidates = await notAlreadyClaimed(
    conn('invoices as i')
      .join('scheduled_services as anchor', 'anchor.id', 'i.scheduled_service_id')
      .whereNot('i.status', 'void')
      .modify((q) => {
        if (sinceDays != null) q.whereRaw('i.created_at >= NOW() - (?::int * INTERVAL \'1 day\')', [Number(sinceDays)]);
      })
      .whereNotNull('anchor.source_estimate_id')
      .whereNull('anchor.recurring_parent_id')
      .where('anchor.is_recurring', true),
    'anchor',
    'i',
  )
    .orderBy('i.created_at', 'asc')
    .select(
      'i.id as invoice_id', 'i.title', 'i.notes', 'i.line_items', 'i.created_at as invoice_created_at',
      'anchor.id as anchor_id', 'anchor.customer_id', 'anchor.source_estimate_id', 'anchor.scheduled_date as anchor_scheduled_date',
    );

  // Pass 1: for every candidate invoice (text-recognized, oldest first),
  // find its RAW window+original-date-matched siblings, then tally which
  // invoice(s) each sibling id matched — a sibling matched by more than one
  // invoice is ambiguous and must be excluded from ALL of them, not just
  // "first one wins".
  const matchesByInvoice = new Map(); // invoiceId -> { row, siblingIds: Set }
  const invoicesBySibling = new Map(); // siblingId -> Set(invoiceId)
  const nearMissSiblingIds = new Set(); // in-window, but its date at invoice creation didn't match ANY candidate invoice's anchor
  const pricedUnitemizedSiblingIds = new Set(); // in-window but priced and not itemized — never inferred
  const matchedSiblingIds = new Set();
  let scanned = 0;
  for (const row of candidates) {
    scanned += 1;
    if (!isCombinedFirstApplicationInvoiceForBackfill(row)) continue;
    // The anchor's application already billed by a DIFFERENT live invoice →
    // not this invoice's group (an unrelated add-on/repair invoice is not).
    if ((await liveBaseApplicationInvoiceVisitIds([row.anchor_id], { excludeInvoiceId: row.invoice_id })).size) continue;
    const anchorDateAtInvoice = await dateAtInstant(conn, hasRescheduleLog, row.anchor_id, row.anchor_scheduled_date, row.invoice_created_at);

    const rawSiblings = await notAlreadyClaimed(
      conn('scheduled_services as s')
        .where('s.customer_id', row.customer_id)
        .where('s.source_estimate_id', row.source_estimate_id)
        .whereNot('s.id', row.anchor_id)
        .whereNull('s.recurring_parent_id')
        .where('s.is_recurring', true)
        // estimated_price is read, not filtered here: a PRICED row is stamped
        // only on itemized-line evidence (see the loop below — Codex r20 P1
        // vs. the pre-push P0 on d8f1c92da1).
        .whereRaw('ABS(EXTRACT(EPOCH FROM (s.created_at - ?::timestamptz))) <= 120', [row.invoice_created_at]),
      's',
    )
      .select('s.id', 's.scheduled_date', 's.estimated_price');
    // A sibling whose application a live invoice already bills was split off
    // by hand: not a covered member. Decided by the base-application identity,
    // never by "any invoice on the row" (Codex r17 P1).
    const splitOff = await liveBaseApplicationInvoiceVisitIds(rawSiblings.map((sib) => sib.id));

    const siblingIds = new Set();
    // Durable acceptance-time evidence that needs no reschedule history at
    // all (Codex r20 P1 — an Intelligence Bar move whose post-commit
    // reschedule_log insert failed leaves no audit row): the invoice's OWN
    // line items name the member when the accept itemized the combined
    // charge (itemizeFirstApplication writes client_id
    // `scheduled_<member id>_primary`). Such a member is stamped regardless
    // of where it sits today.
    const itemizedMemberIds = itemizedMemberIdsFromInvoiceLines(row.line_items);
    for (const sib of rawSiblings) {
      if (splitOff.has(String(sib.id))) continue;
      if (itemizedMemberIds.has(String(sib.id))) {
        siblingIds.add(sib.id);
        matchedSiblingIds.add(sib.id);
        if (!invoicesBySibling.has(sib.id)) invoicesBySibling.set(sib.id, new Set());
        invoicesBySibling.get(sib.id).add(row.invoice_id);
        continue;
      }
      // A PRICED row with no itemized line is never inferred into a group
      // (Codex pre-push P0 on d8f1c92da1): a separately priced same-estimate
      // program created in the same accept window bills itself at
      // completion, and stamping it would make the stamp-aware lookup reuse
      // the combined invoice for it — suppressing its legitimate charge. A
      // covered member that staff priced LATER is stamped only on the
      // itemized-line evidence above; otherwise it is logged for hand review
      // rather than guessed. Fails toward not stamping.
      if (sib.estimated_price != null) { pricedUnitemizedSiblingIds.add(sib.id); continue; }
      const sibDateAtInvoice = await dateAtInstant(conn, hasRescheduleLog, sib.id, sib.scheduled_date, row.invoice_created_at);
      if (anchorDateAtInvoice && sibDateAtInvoice && sibDateAtInvoice === anchorDateAtInvoice) {
        siblingIds.add(sib.id);
        matchedSiblingIds.add(sib.id);
        if (!invoicesBySibling.has(sib.id)) invoicesBySibling.set(sib.id, new Set());
        invoicesBySibling.get(sib.id).add(row.invoice_id);
      } else {
        nearMissSiblingIds.add(sib.id);
      }
    }
    matchesByInvoice.set(row.invoice_id, { row, siblingIds });
  }

  // Pass 2: resolve ambiguity, then stamp — invoice order is the same
  // created_at-ascending order the candidates were read in.
  let stamped = 0;
  let ambiguous = 0;
  const ambiguousSiblingIds = new Set();
  for (const [siblingId, invoiceIds] of invoicesBySibling) {
    if (invoiceIds.size > 1) ambiguousSiblingIds.add(siblingId);
  }
  if (ambiguousSiblingIds.size) {
    ambiguous = ambiguousSiblingIds.size;
    logger.warn(`[estimate-first-application-invoice] backfill: ${ambiguous} sibling row(s) matched more than one candidate invoice within the accept-time window and date-at-invoice evidence — left unstamped for hand review: ${[...ambiguousSiblingIds].join(', ')}`);
  }
  // Anything in the window that never matched ANY invoice's anchor date,
  // and was never resolved as ambiguous either, fell inside the timing
  // window with no same-trip evidence this backfill could confirm.
  const unresolvedNearMisses = [...nearMissSiblingIds].filter((id) => !matchedSiblingIds.has(id) && !ambiguousSiblingIds.has(id));
  const pricedSkipped = [...pricedUnitemizedSiblingIds].filter((id) => !matchedSiblingIds.has(id));
  if (pricedSkipped.length) {
    logger.warn(`[estimate-first-application-invoice] backfill: ${pricedSkipped.length} priced row(s) created within the accept-time window of a combined invoice were not inferred as members (no itemized line names them) — review by hand if any was a covered visit priced later: ${pricedSkipped.join(', ')}`);
  }
  if (unresolvedNearMisses.length) {
    logger.warn(`[estimate-first-application-invoice] backfill: ${unresolvedNearMisses.length} row(s) created within the accept-time window of a combined invoice, but with no matching date-at-invoice evidence — left unstamped for hand review: ${unresolvedNearMisses.join(', ')}`);
  }

  for (const { row, siblingIds } of matchesByInvoice.values()) {
    const eligibleSiblingIds = [...siblingIds].filter((id) => !ambiguousSiblingIds.has(id));
    // A single-program invoice (no eligible, non-ambiguous sibling) is
    // never stamped as a pair.
    if (!eligibleSiblingIds.length) continue;
    stamped += await stampGroupRevalidated(conn, {
      invoiceId: row.invoice_id, anchorId: row.anchor_id, siblingIds: eligibleSiblingIds, extendPartialGroups,
    });
  }
  return { scanned, stamped, ambiguous };
}

// Pass 1 reads eligibility outside any transaction (the runtime
// reconciliation runs on the global connection), so a price edit, a
// standalone invoice mint or an accept-time stamp can land between the read
// and the write (Codex pre-push P1 on 671efec4fe, PR #5021). Each group is
// therefore re-checked and written in ONE transaction with the invoice and
// member rows locked: the invoice still live, the anchor still unstamped
// (or, on the unbounded run, stamped to this invoice) and still not billed by
// another live base-application invoice — otherwise nothing in the group is
// stamped, never siblings without their anchor. Each sibling must still be
// unstamped, not split off, and unpriced unless the invoice itemizes it.
// Never overwrites; returns the rows actually written.
async function liveBaseApplicationInvoiceVisitIdsOn(q, visitIds, { excludeInvoiceId = null } = {}) {
  if (!visitIds.length) return new Set();
  const { CANCELLED_SERVICE_RESOLVED_STATUSES } = require('./invoice');
  const rows = await q('invoices')
    .whereIn('scheduled_service_id', visitIds)
    .whereNotIn('status', CANCELLED_SERVICE_RESOLVED_STATUSES)
    .modify((qb) => { if (excludeInvoiceId) qb.whereNot('id', excludeInvoiceId); })
    .select('id', 'scheduled_service_id', 'line_items');
  return new Set(rows.filter((r) => invoiceBillsBaseApplication(r)).map((r) => String(r.scheduled_service_id)));
}

async function stampGroupRevalidated(conn, { invoiceId, anchorId, siblingIds, extendPartialGroups = false }) {
  return conn.transaction(async (trx) => {
    const invoice = await trx('invoices').where({ id: invoiceId }).forUpdate().first('id', 'status', 'line_items', 'scheduled_service_id');
    if (!invoice || invoice.status === 'void' || String(invoice.scheduled_service_id) !== String(anchorId)) return 0;
    const locked = await trx('scheduled_services').whereIn('id', [anchorId, ...siblingIds]).orderBy('id').forUpdate()
      .select('id', 'first_application_invoice_id', 'estimated_price');
    const byId = new Map(locked.map((r) => [String(r.id), r]));
    const anchor = byId.get(String(anchorId));
    const anchorStamp = anchor && anchor.first_application_invoice_id;
    if (!anchor || (anchorStamp != null && !(extendPartialGroups && String(anchorStamp) === String(invoiceId)))) return 0;
    if ((await liveBaseApplicationInvoiceVisitIdsOn(trx, [anchorId], { excludeInvoiceId: invoiceId })).size) return 0;
    const itemized = itemizedMemberIdsFromInvoiceLines(invoice.line_items);
    const splitOff = await liveBaseApplicationInvoiceVisitIdsOn(trx, siblingIds);
    const stillEligible = siblingIds.filter((id) => {
      const sib = byId.get(String(id));
      if (!sib || sib.first_application_invoice_id != null || splitOff.has(String(id))) return false;
      return itemized.has(String(id)) || sib.estimated_price == null;
    });
    if (!stillEligible.length) return 0;
    return trx('scheduled_services').whereIn('id', [anchorId, ...stillEligible])
      .whereNull('first_application_invoice_id')
      .update({ first_application_invoice_id: invoiceId });
  });
}

// Freeze the accept route's per-service authority while it still exists.
// Later closeout must never reconstruct this split from mutable plan prices.
// Unknown composition keeps the existing aggregate and requires office review.
async function itemizeFirstApplication({ estimateId, customerId, scheduledServiceId, rowAmounts, rowDiscounts = [], line }, conn = db) {
  if (process.env.GATE_VISIT_CLOSEOUT !== 'true' || !scheduledServiceId
      || !Array.isArray(rowAmounts) || rowAmounts.length < 2) return [line];
  if (!Array.isArray(rowDiscounts) || rowDiscounts.some((amount) => !Number.isFinite(amount) || amount < 0)) return [line];
  const first = await conn('scheduled_services').where({ id: scheduledServiceId,
    customer_id: customerId, source_estimate_id: estimateId }).first();
  if (!first || first.recurring_parent_id) return [line];
  const members = await conn('scheduled_services').where({ customer_id: customerId,
    source_estimate_id: estimateId, scheduled_date: first.scheduled_date }).whereNull('recurring_parent_id').orderBy('id');
  const { recurringServiceKey, reservedAcceptPerVisitSplit } = require('./estimate-converter');
  const identity = (member) => ({ name: member.service_type });
  // The invoice's separate labeled credit stays intact. Restore only each
  // row's exact accepted credit slice to its gross line, never apportion anew.
  const grossRows = rowAmounts.map((row, index) => ({ ...row,
    amount: Math.round((Number(row.amount) + Number(rowDiscounts[index] || 0)) * 100) / 100,
  }));
  const split = reservedAcceptPerVisitSplit({ reservedPrice: line.unit_price,
    reservedService: identity(members[0]), promotedServices: members.slice(1).map(identity), rowAmounts: grossRows });
  if (!split) return [line];
  const amounts = [split.reserved, ...split.promoted];
  return members.map((member, index) => ({
    ...line, client_id: `scheduled_${member.id}_primary`,
    accepted_service_type: member.service_type, accepted_service_id: member.service_id,
    description: rowAmounts.find((row) => recurringServiceKey(row) === recurringServiceKey(identity(member)))?.name
      || member.service_type,
    quantity: 1, unit_price: amounts[index], amount: amounts[index],
  }));
}

// The visit's accept-time first-application stamp
// (scheduled_services.first_application_invoice_id — written once, by
// estimate-converter.js stampCombinedFirstApplicationInvoiceCoverage or the
// history backfill below). The stamp is write-once and never cleared, so a
// NON-NULL value on the caller's svc row cannot be stale and is trusted. A
// NULL can be: the sweep's runtime reconciliation may stamp the row after the
// caller read it (Codex r2/r3 P1 on #5237 — Charge Now, then completion), and
// a narrow select leaves the column undefined (Codex round 14 on #5021).
// Both re-read by id, so every consumer (the stamped lookup, the coverage
// verdict, the priced-member gate) decides from the current stamp. No svc.id
// → nothing to read; treated as unstamped (pure/unit-test callers).
async function readFirstApplicationStamp(svc, conn) {
  if (svc?.first_application_invoice_id) return svc.first_application_invoice_id;
  if (!svc?.id || !conn) return null;
  const row = await conn('scheduled_services').where({ id: svc.id }).first('first_application_invoice_id');
  return row?.first_application_invoice_id || null;
}

// Is svc a NON-ANCHOR member of its own stamped combined invoice? (Codex r21
// P1 on PR #5021, deferred to this follow-up.) first_application_invoice_id
// is stamped on the ANCHOR too (stampCombinedFirstApplicationInvoiceCoverage
// / the backfill above stamp the anchor alongside every covered sibling), so
// carrying a stamp alone never says whether THIS row is the invoice's own
// anchor or a covered member — only comparing the stamped invoice's OWN
// scheduled_service_id (its anchor) against svc.id does. This is a WIDENING
// GATE for isSiblingCoverageEligibleVisit's priced branch, never a mint
// decision itself: siblingInvoiceCoverageVerdict / combinedInvoiceVoidedWithoutLiveReplacement
// still make the actual (fail-closed) call once a caller is eligible to ask
// them. A missing svc.id/conn, no stamp, or a missing invoice row all
// read false (a read ERROR reads true — see the catch) — never toward a false "is a member" that would wrongly widen
// an ANCHOR's own priced mint (see that predicate's own header for why an
// anchor must never reach the terminal-match-ahead-of-own-visit branches
// this gate exists to keep the anchor out of).
async function isPricedCoveredMemberVisit(svc, conn) {
  if (!svc?.id || !conn) return false;
  try {
    const stampedInvoiceId = await readFirstApplicationStamp(svc, conn);
    if (!stampedInvoiceId) return false;
    const invoice = await conn('invoices').where({ id: stampedInvoiceId }).first('scheduled_service_id');
    if (!invoice?.scheduled_service_id) return false;
    if (String(invoice.scheduled_service_id) === String(svc.id)) return false;
    // An own REFUNDED invoice keeps the member in review even beside a live
    // replacement (Codex r3 P2 on #5237): completion parks whenever a
    // refunded and a live invoice coexist, since the refund may still fail
    // and restore the original payment. Staying a member routes Charge Now
    // and the schedule sheet to pricedCoveredMemberOwnRefundHold → review.
    if (await pricedCoveredMemberOwnRefundHold(svc, conn)) return true;
    // Split off by hand (#5237 review P2): a member whose base application a
    // live invoice of its OWN already bills is no longer covered — the same
    // split evidence the backfill and the sweep use
    // (liveBaseApplicationInvoiceVisitIdsOn). Without this, a stamped visit
    // the office split off could never be collected in person again.
    return !(await liveBaseApplicationInvoiceVisitIdsOn(conn, [svc.id])).size;
  } catch (err) {
    // A failed read is NOT "unstamped" (pre-push P1 on acb6a0ad54): false
    // would let a covered priced member fall through to minting its own
    // price — the double charge this gate exists to stop. Unknown admits the
    // visit to the coverage verdict, which fails closed on its own (an error
    // or ambiguous match refuses / holds for review, never mints).
    require('./logger').warn(`[estimate-first-application-invoice] isPricedCoveredMemberVisit read failed for ${svc.id}; routing to the fail-closed coverage check: ${err?.message || err}`);
    return true;
  }
}

// Completion's in-lock mint guard (Codex r4 P1 on #5237). Completion decides
// "nothing covers this visit" from reads taken BEFORE its mint lock, and the
// runtime reconciliation (stampGroupRevalidated) can stamp the visit between
// those reads and the mint. Call this under the visit's row lock (after
// acquireScheduledMintLockChain's FOR UPDATE): stampGroupRevalidated locks
// the same scheduled_services rows before it stamps, so the read here is
// authoritative. Either the stamp committed first and this refuses, or the
// stamper waits for this mint, sees the visit's own live invoice
// (liveBaseApplicationInvoiceVisitIdsOn) and leaves it unstamped. A refusal
// is a retryable 409: the retry's pre-lock lookup now sees the stamp and
// reuses the combined invoice. A read error refuses too (isPricedCovered-
// MemberVisit reads true on error), so a failed read never mints.
async function refuseCoveredMemberMintInTrx(trx, scheduledServiceId) {
  if (!scheduledServiceId) return;
  if (!(await isPricedCoveredMemberVisit({ id: scheduledServiceId }, trx))) return;
  const e = new Error('This visit is billed on its trip\'s combined first-application invoice — no separate invoice was created.');
  e.status = 409;
  e.statusCode = 409;
  e.code = 'FIRST_APPLICATION_COVERED';
  throw e;
}

// A priced covered member's OWN refunded base-application invoice (#5237
// review r2 P2): isPricedCoveredMemberVisit's own "split off by hand" check
// (liveBaseApplicationInvoiceVisitIdsOn, above) only excludes a LIVE own
// invoice — a REFUNDED one leaves the member still coverage-eligible there,
// so the ordinary sibling verdict would report 'covered' on the (still
// live) combined invoice while completion — which checks THIS VISIT's own
// refunded invoice FIRST, unconditionally, before ever consulting the
// sibling group at all (completionTerminalInvoiceLookup,
// completion-invoice-candidate.js) — parks it for manual review instead.
// Called ONLY by the priced-covered-member widening's own entry points
// (resolveScheduledServiceCharge, siblingCoverageForSchedule), and only
// once isPricedCoveredMemberVisit has already confirmed a genuine covered
// member, so it can never disagree with completion for exactly the input
// this widening admits — reuses completion's own classifier rather than a
// second one. Deliberately does NOT swallow a read failure the way
// isPricedCoveredMemberVisit does: this decides a REFUSAL, not a widening
// gate, so a failure here must propagate to the caller's own fail-closed
// verdict handling, never silently fall through to an ordinary mint.
async function pricedCoveredMemberOwnRefundHold(svc, conn) {
  if (!svc?.id || !conn) return null;
  const { completionTerminalInvoiceLookup } = require('./completion-invoice-candidate');
  return completionTerminalInvoiceLookup(conn, { scheduledServiceId: svc.id });
}

// The candidate-row query. Unstamped: byte-identical to the pre-stamp
// date-matched query (estimate + customer + the first visit's CURRENT date).
// Stamped (Codex round 14 P1, PR #5021): the stamped invoice row itself
// (whatever date its anchor now sits on) and every invoice on the stamped
// invoice's own anchor visit (its invoices.scheduled_service_id — so a live
// replacement minted on the anchor is seen too), and NOTHING date-matched
// (Codex r17 P1: another group's same-day invoice must never compete). Date matching alone lost the combined invoice the moment a covered
// sibling moved to another day, and completion / Charge Now would then mint a
// second charge for an application the combined invoice already bills (or
// already collected). Still customer-scoped and still void-excluded for every
// branch; lockRows/noWait apply to the whole widened query exactly as before.
function firstApplicationCandidateQuery(conn, {
  customerId, sourceEstimateId, scheduledDate, stampedInvoiceId,
}) {
  const query = conn('invoices as i')
    .join('scheduled_services as first_visit', 'i.scheduled_service_id', 'first_visit.id')
    .where('i.customer_id', customerId);
  if (!stampedInvoiceId) {
    return query
      .where('first_visit.source_estimate_id', sourceEstimateId)
      .where('first_visit.scheduled_date', scheduledDate);
  }
  // Stamped: ONLY the stamped invoice and the invoices on its anchor row —
  // never the date-matched rows. A stamped sibling rescheduled onto a day
  // used by ANOTHER combined-invoice group under the same customer and
  // estimate would otherwise surface that group's invoice beside its own,
  // and the classifier could park against or reuse (and send a pay link
  // for) an invoice that does not cover this visit (Codex r17 P1, PR #5021).
  // The stamp is the authoritative accept-time fact; date matching exists
  // only for unstamped history.
  return query.where(function stampedGroupOnly() {
    this.where('i.id', stampedInvoiceId)
      .orWhereIn('i.scheduled_service_id', function stampedAnchorVisit() {
        this.select('scheduled_service_id').from('invoices').where('id', stampedInvoiceId);
      });
  });
}

async function findFirstApplicationInvoiceForEstimateService(svc, conn = db, { lockRows = false, noWait = false } = {}) {
  const sourceEstimateId = svc?.source_estimate_id;
  const customerId = svc?.customer_id;
  const scheduledDate = dateOnly(svc?.scheduled_date);
  if (!sourceEstimateId || !customerId) return { invoice: null, liveBeside: null };
  const stampedInvoiceId = await readFirstApplicationStamp(svc, conn);
  if (!scheduledDate && !stampedInvoiceId) return { invoice: null, liveBeside: null };

  // lockRows (transactional callers only): FOR UPDATE OF i returns the
  // LATEST committed row versions and holds them to commit — a plain select
  // classifies snapshot statuses that a concurrent refund/cancel/restore
  // can invalidate before the caller acts (codex #3456 hardening).
  //
  // `noWait` (codex round-6 P1, pre-push): a caller that took the
  // estimate.deposit.ledger advisory lock (estimate-deposits.js) BEFORE
  // this row lock — the schedule mint's own sibling recheck
  // (scheduled-invoice-mint.js) does exactly this to close the 'none'/
  // 'none' double-mint race — can otherwise deadlock against
  // withInvoiceDepositSettlement, which locks THIS SAME invoice row first
  // and only afterward requests that same ledger lock (the established
  // "invoice row before ledger lock" order documented on
  // acquireEstimateDepositLedgerLock). NOWAIT breaks that cycle: instead of
  // blocking (and potentially deadlocking) on a row someone else holds,
  // this throws immediately (Postgres 55P03) and the caller's own
  // catch-all treats ANY lookup failure as `{ status: 'error' }` — a
  // retryable refusal, never a silent double-mint. Default false keeps
  // every other lockRows:true caller (completion's own re-check) byte-
  // identical — it does not take the ledger lock first, so it has no
  // reason to fail fast here.
  let query = firstApplicationCandidateQuery(conn, {
    customerId, sourceEstimateId, scheduledDate, stampedInvoiceId,
  })
    // INTENTIONALLY retains refunded/cancelled rows (status quo — codex #3456
    // narrowed scope): this lookup reaches SIBLING scheduled services of the
    // same estimate/date. A REFUNDED sibling first-application invoice keeps
    // suppressing the completion mint exactly as before (no replacement is
    // minted, nothing to reconcile on a bounced refund); the own-visit
    // terminal case is handled in routes/admin-dispatch.js
    // (completionTerminalInvoiceLookup → manual-billing alert).
    .whereNot('i.status', 'void')
    .orderBy('i.created_at', 'desc')
    .select('i.*');
  if (lockRows) query = noWait ? query.forUpdate('i').noWait() : query.forUpdate('i');
  const rows = await query;
  return classifyFirstApplicationMatches(rows, stampedInvoiceId);
}

// Pure: turn the candidate rows (created_at DESC) into the lookup's result.
function classifyFirstApplicationMatches(rows, stampedInvoiceId) {
  // A canceled/cancelled match must not end the scan (codex #3456 P1): the
  // caller drops such a row from reuse (splitTerminalCompletionInvoice), and
  // returning ONLY the newest match would then read as "no suppressor" while
  // an OLDER live first-application invoice remains collectible — the mint
  // would cut a second invoice for the same application. So skip the
  // resolved non-refunded vocabulary; and because there is NO reliable
  // refund-event clock to order a refunded match against a live one
  // (invoices carry no refunded_at; created_at is mint time; updated_at
  // moves on unrelated edits — codex #3456 rounds 4–6), a REFUNDED match
  // wins whenever one exists, in ANY mint order: the caller's terminal path
  // parks the visit for a human instead of auto-sending a pay link a
  // bounced refund could turn into a double collection. When both exist,
  // the newest live match rides along as `liveBeside` so the caller's
  // manual-billing alert directs staff to collect THAT invoice instead of
  // creating a duplicate (codex #3456 r7) — same shape as the own-visit
  // reconciliation. All-canceled is NOT a plain fall-through to the mint
  // (codex #3456 late round): the acceptance-time first-application invoice
  // carries the ONE-TIME SETUP FEE beside the visit charge
  // (estimate-public.js accept mints them as one invoice), so an ordinary
  // completion remint would recreate only the visit charge and silently
  // drop the fee. A canceled acceptance match with NO live replacement is
  // surfaced as `canceledSetupFee` — the caller parks the manual-billing
  // alert (bill BOTH charges by hand) instead of partial-reminting. A live
  // match still wins over it (the replacement already stands).
  //
  // The STAMPED invoice row itself is a match on the stamp alone — the
  // durable accept-time fact outranks title/notes text, which
  // InvoiceService.update lets staff edit on an unpaid invoice. Every other
  // row (date-matched, or a replacement on the stamped anchor) still has to
  // pass the text recognizer, exactly as before.
  const InvoiceService = require('./invoice');
  const skipStatuses = InvoiceService.CANCELLED_SERVICE_RESOLVED_STATUSES.filter((s) => s !== 'refunded');
  const isStampedRow = (row) => stampedInvoiceId != null && String(row.id) === String(stampedInvoiceId);
  const allMatches = (rows || []).filter((row) => isStampedRow(row) || isAutoGeneratedPayPerApplicationInvoice(row));
  const matches = allMatches.filter((row) => !skipStatuses.includes(row.status));
  const refunded = matches.find((row) => row.status === 'refunded') || null;
  const live = matches.find((row) => row.status !== 'refunded') || null; // created_at DESC → newest live match
  if (refunded) return { invoice: refunded, liveBeside: live };
  if (live) return { invoice: live, liveBeside: null };
  // Only a canceled acceptance invoice that ACTUALLY carried a setup-fee
  // line parks the completion — a canceled "first application only"
  // acceptance invoice has no fee to lose, and parking it would instruct
  // staff to bill a nonexistent charge (codex P0): those remint normally.
  const canceledSetupFee = allMatches.find((row) => skipStatuses.includes(row.status)
    && row.status !== 'void' && invoiceContainsSetupFeeLine(row)) || null;
  return canceledSetupFee ? { invoice: null, liveBeside: null, canceledSetupFee } : { invoice: null, liveBeside: null };
}

// Does this invoice row carry the one-time setup-fee CHARGE? Authoritative
// source: a parsed line_items entry (the acceptance mint writes
// 'WaveGuard Membership — one-time setup fee') — but only a POSITIVE line
// whose text does not say the fee was WAIVED: the converter's real
// annual-prepay line reads "12 months prepaid (setup fee waived)", and
// counting it as a billed fee would let a refunded prepay read as
// fee-collected while nothing was ever billed for it (Codex P0, pre-push
// round 13). Provenance fallback for rows without parseable line items:
// the acceptance notes name the fee only when it was charged
// ("$99 setup fee plus first application" vs "first application only"),
// with the same waived-language rejection.
function invoiceContainsSetupFeeLine(row) {
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (Array.isArray(items) && items.length) {
    return invoiceHasPositiveSetupFeeLine({ line_items: items });
  }
  const notes = String(row?.notes || '');
  return /setup fee/i.test(notes) && !/setup fee waiv/i.test(notes);
}

// Does this invoice bill the BASE plan application? Identity comes from
// the ONE shared predicate (InvoiceService.lineIsBaseApplication — the
// same classifier the switch-supersede restore and prepay-switch undo
// use), so line-identity changes land in one place. This wrapper adds
// the BILLING-EVIDENCE layer its callers need: the line must carry a
// POSITIVE amount (a refunded/credited base line is not the application
// being billed — Codex P0 rounds 6–11), and unreadable rows FAIL CLOSED
// (prove nothing): the callers skip parking or resolve alerts on this
// evidence.
function invoiceBillsBaseApplication(row) {
  const { lineIsBaseApplication } = require('./invoice');
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (!Array.isArray(items) || !items.length) return false;
  return items.some((li) => {
    const qty = li?.quantity != null ? Number(li.quantity) : 1;
    const amt = li?.amount != null ? Number(li.amount) : Number(li?.unit_price) * qty;
    return Number.isFinite(amt) && amt > 0 && lineIsBaseApplication(li);
  });
}

// The amount of the invoice's positive, non-waived one-time setup-fee line
// (null when none) — the shared identity invoiceHasPositiveSetupFeeLine
// checks: description mentions "setup fee" but not "waiv" (the converter's
// annual-prepay line reads "12 months prepaid (setup fee waived)" and would
// otherwise false-match the broader substring test — Codex P0, pre-push
// round 17), and the line carries a positive amount.
function positiveSetupFeeLineAmount(row) {
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (!Array.isArray(items) || !items.length) return null;
  for (const li of items) {
    const desc = String(li?.description || '');
    if (!/setup fee/i.test(desc) || /waiv/i.test(desc)) continue;
    const qty = li?.quantity != null ? Number(li.quantity) : 1;
    const amt = li?.amount != null ? Number(li.amount) : Number(li?.unit_price) * qty;
    if (Number.isFinite(amt) && amt > 0) return amt;
  }
  return null;
}

// STRICT billed-fee evidence for OBLIGATION-CLEARING and ALERT-RESOLVING
// decisions: a positive parsed non-waived setup-fee LINE, no notes
// fallback — provenance text on an unreadable row proves nothing about
// money actually billed (Codex P0, pre-push round 17).
// invoiceContainsSetupFeeLine (above) keeps its notes fallback for the
// #3474 canceledSetupFee PARKING decision, where matching errs toward
// caution (an alert), never toward clearing an obligation.
function invoiceHasPositiveSetupFeeLine(row) {
  return positiveSetupFeeLineAmount(row) != null;
}

// An independent setup-fee document does not cover a performed application.
// Unreadable charges cannot establish the fee-only exception to packet ownership.
function invoiceContainsOnlySetupFeeCharges(row) {
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { return false; }
  }
  if (!Array.isArray(items) || !items.length) return false;
  let hasFee = false;
  for (const line of items) {
    const amount = line?.amount != null ? Number(line.amount)
      : Number(line?.unit_price) * (line?.quantity != null ? Number(line.quantity) : 1);
    if (!Number.isFinite(amount)) return false;
    if (amount <= 0) continue;
    const description = String(line?.description || '');
    if (!/^(?:(?:WaveGuard Membership|Bait Station Setup)\s*[—–-]\s*)?(?:one-time )?setup fee$/i.test(description.trim())
        || require('./invoice').lineIsBaseApplication(line)) return false;
    hasFee = true;
  }
  return hasFee;
}

// Classify rows only after the caller has acquired its own transaction and
// row locks. Setup-fee coverage is estimate-wide; application coverage is
// visit-date scoped, with a missing date failing closed as a possible match.
// Status remains caller-owned because packet ownership survives terminal
// invoice states while adoption deliberately distinguishes them.
function classifyAcceptedEstimateInvoiceCoverage(row, applicationDate) {
  const rowDate = dateOnly(row?.service_date || row?.scheduled_date);
  const targetDate = dateOnly(applicationDate);
  return {
    hasSetupFee: invoiceHasPositiveSetupFeeLine(row),
    setupFeeOnly: invoiceContainsOnlySetupFeeCharges(row),
    matchesApplicationDate: !rowDate || !targetDate || rowDate === targetDate,
  };
}

// Cents totals for coverage comparison (Codex PR r7 P1): boolean
// any-positive-line evidence lets a $9.90 typo retire a $99 obligation —
// resolution compares SUMMED live coverage against the frozen expected
// amounts persisted on the alert.
function sumPositiveSetupFeeCents(row) {
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (!Array.isArray(items)) return 0;
  return items.reduce((sum, li) => {
    const desc = String(li?.description || '');
    if (!/setup fee/i.test(desc) || /waiv/i.test(desc)) return sum;
    const qty = li?.quantity != null ? Number(li.quantity) : 1;
    const amt = li?.amount != null ? Number(li.amount) : Number(li?.unit_price) * qty;
    return Number.isFinite(amt) && amt > 0 ? sum + Math.round(amt * 100) : sum;
  }, 0);
}

// Acceptance invoices stay editable until delivery, so their line JSON cannot
// authorize a setup charge. Compare it with acceptance-frozen evidence: the
// estimate owns the WaveGuard fee and setup_fee_claims owns any rodent fee.
async function acceptanceSetupFeeMatchesAuthority({ invoice, estimateId }, conn = db) {
  const billedCents = sumPositiveSetupFeeCents(invoice);
  const estimate = await conn('estimates').where({ id: estimateId,
    customer_id: invoice.customer_id, status: 'accepted' }).first('estimate_data');
  if (!estimate) return false;
  const { parseEstimateData, snapshotShowsSetupFee } = require('./setup-fee-obligation')._private;
  const estimateData = parseEstimateData(estimate.estimate_data);
  const shown = estimateData.acceptedSetupFeeAmount == null
    ? snapshotShowsSetupFee(estimateData)
    : { evidence: 'shown', amount: estimateData.acceptedSetupFeeAmount };
  const waveGuardCents = shown.evidence === 'shown' && shown.amount != null
    ? Math.round(Number(shown.amount) * 100) : (shown.evidence === 'shown' ? NaN : 0);
  const claim = await conn('setup_fee_claims').where({ invoice_id: invoice.id })
    .forUpdate().noWait().first('amount', 'estimate_id');
  if (claim?.estimate_id && String(claim.estimate_id) !== String(estimateId)) return false;
  const claimCents = claim ? Math.round(Number(claim.amount) * 100) : 0;
  if (![waveGuardCents, claimCents].every(Number.isSafeInteger)
      || Math.min(waveGuardCents, claimCents) < 0 || (claim && claimCents === 0)) return false;
  return billedCents === waveGuardCents + claimCents;
}

function sumBaseApplicationCents(row) {
  let items = row?.line_items;
  if (typeof items === 'string') {
    try { items = JSON.parse(items); } catch { items = null; }
  }
  if (!Array.isArray(items)) return 0;
  const { lineIsBaseApplication } = require('./invoice');
  return items.reduce((sum, li) => {
    const qty = li?.quantity != null ? Number(li.quantity) : 1;
    const amt = li?.amount != null ? Number(li.amount) : Number(li?.unit_price) * qty;
    return Number.isFinite(amt) && amt > 0 && lineIsBaseApplication(li) ? sum + Math.round(amt * 100) : sum;
  }, 0);
}

module.exports = {
  itemizeFirstApplication,
  dateOnly,
  findFirstApplicationInvoiceForEstimateService,
  // Shared with billing-lane.js's REFUSE-AFTER-A-VOID guard so the lookup and
  // its void fallback can never disagree about which rows form the group.
  firstApplicationCandidateQuery,
  readFirstApplicationStamp,
  isPricedCoveredMemberVisit,
  refuseCoveredMemberMintInTrx,
  pricedCoveredMemberOwnRefundHold,
  isAutoGeneratedPayPerApplicationInvoice,
  isInvoiceModeRecurringAcceptInvoice,
  isCombinedFirstApplicationInvoiceForBackfill,
  itemizedMemberIdsFromInvoiceLines,
  backfillFirstApplicationInvoiceStamps,
  stampGroupRevalidated,
  invoiceContainsSetupFeeLine,
  invoiceHasPositiveSetupFeeLine,
  positiveSetupFeeLineAmount,
  invoiceContainsOnlySetupFeeCharges,
  classifyAcceptedEstimateInvoiceCoverage,
  invoiceBillsBaseApplication,
  sumPositiveSetupFeeCents,
  acceptanceSetupFeeMatchesAuthority,
  sumBaseApplicationCents,
};
